package com.hospital.system.service; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; @Service public class ReportService {private final JdbcTemplate db; public ReportService(JdbcTemplate db){this.db=db;} public Map<String,Object> dashboard(){Map<String,Object> m=new LinkedHashMap<>();m.put("totalPatients",db.queryForObject("SELECT COUNT(*) FROM patient",Long.class));m.put("totalDoctors",db.queryForObject("SELECT COUNT(*) FROM doctor",Long.class));m.put("totalAppointments",db.queryForObject("SELECT COUNT(*) FROM appointment",Long.class));m.put("todayAppointments",db.queryForObject("SELECT COUNT(*) FROM appointment WHERE appointment_date=CURRENT_DATE",Long.class));m.put("totalBills",db.queryForObject("SELECT COUNT(*) FROM bill",Long.class));m.put("paidBills",db.queryForObject("SELECT COUNT(*) FROM bill WHERE status='PAID'",Long.class));m.put("pendingBills",db.queryForObject("SELECT COUNT(*) FROM bill WHERE status<>'PAID'",Long.class));m.put("totalRevenue",db.queryForObject("SELECT COALESCE(SUM(amount),0) FROM payment",java.math.BigDecimal.class));return m;} public List<Map<String,Object>> revenue(){return db.queryForList("SELECT payment_date AS date,SUM(amount) AS revenue FROM payment GROUP BY payment_date ORDER BY payment_date DESC");} public List<Map<String,Object>> appointments(){return db.queryForList("SELECT appointment_date AS date,COUNT(*) AS appointment_count FROM appointment GROUP BY appointment_date ORDER BY appointment_date DESC");} public List<Map<String,Object>> pending(){return db.queryForList("SELECT * FROM v_bill_summary WHERE status<>'PAID' ORDER BY balance DESC");} public List<Map<String,Object>> paid(){return db.queryForList("SELECT * FROM v_bill_summary WHERE status='PAID' ORDER BY bill_id DESC");} public List<Map<String,Object>> history(Long id){return db.queryForList("CALL get_patient_appointments(?)",id);} }
